 ('webhook','{url,secret,meta,header_authorization_encrypted,is_active}',false),
 ('hook_task','{payload_content,request_content,response_content,is_delivered}',false),
 ('mirror','{remote_address,lfs_endpoint,interval,next_update_unix}',false),
 ('push_mirror','{remote_address,interval,sync_on_commit,last_error}',false),
 ('repository','{original_url,is_mirror}',false),
 ('login_source','{cfg,is_active,is_sync_enabled}',false),
 ('external_login_user','{raw_data,access_token,access_token_secret,refresh_token,expires_at}',false),
 ('task','{payload_content,message}',false);
CREATE FUNCTION pg_temp.business_fingerprints() RETURNS TABLE(table_name text, row_count bigint, fingerprint text)
LANGUAGE plpgsql AS $$ DECLARE r record; BEGIN
 FOR r IN SELECT c.relname,coalesce(v.columns,'{}'::text[]) AS excluded
 FROM pg_class c LEFT JOIN pg_temp.revocations v ON v.table_name=c.relname
 WHERE c.relnamespace='public'::regnamespace AND c.relkind='r' AND NOT coalesce(v.delete_rows,false)
 ORDER BY c.relname LOOP
  RETURN QUERY EXECUTE format('SELECT %L::text,count(*)::bigint,encode(sha256(convert_to(coalesce(string_agg(h, '''' ORDER BY h COLLATE "C"),''''),''UTF8'')),''hex'') FROM (SELECT encode(sha256(convert_to((to_jsonb(t)-%L::text[])::text,''UTF8'')),''hex'') h FROM public.%I t)x',r.relname,r.excluded,r.relname);
 END LOOP;
END $$;

